                'negative_marks' => 0.25,
                'question' => 'The Royal Commerce Club received ₹1,80,000 as subscriptions during FY 2024-25. The accounting records reveal:
- Subscriptions outstanding on 1 April 2024: ₹24,000
- Subscriptions received in advance on 1 April 2024 (for FY 2024-25): ₹15,000
- Subscriptions received in advance on 31 March 2025 (for FY 2025-26): ₹18,000
- Subscriptions outstanding on 31 March 2025: ₹32,000 (including ₹6,000 still in arrears for FY 2023-24)
What amount should be credited as subscription income in the Income & Expenditure Account for FY 2024-25?',
                'explanation' => 'Subscription income to be credited to Income & Expenditure Account:
Cash received: ₹1,80,000
Add: Advance at beginning (1 April 2024): +₹15,000
Less: Advance at end (31 March 2025): -₹18,000
Less: Outstanding at beginning (1 April 2024): -₹24,000
Add: Outstanding at end (31 March 2025): +₹32,000
Net Subscription Income = ₹1,80,000 + ₹15,000 - ₹18,000 - ₹24,000 + ₹32,000 = ₹1,85,000.',
                'tags' => 'NPO;Subscription Accounting;Accrual Concept',
                'source' => 'ICAI CA Foundation / B.Com Honours Standard',
                'status' => 'published',
                'option_a' => '₹1,79,000',
