                'usage' => 'both',
                'marks' => 1,
                'negative_marks' => 0.25,
                'question' => 'On 31 March 2025, the Cash Book of Apex Traders showed an overdraft balance of ₹65,000. On comparing it with the Bank Pass Book:
1. Cheques issued for ₹28,000 were not presented for payment until 4 April.
2. Cheques paid into the bank for ₹36,000 were credited only on 6 April.
3. Bank interest on overdraft ₹3,200 and incidental bank charges ₹800 were debited in the pass book only.
4. A customer directly deposited ₹14,000 into the bank account, recorded only in the pass book.
What is the balance / overdraft as per the Bank Pass Book?',
                'explanation' => 'Starting with Overdraft as per Cash Book (-₹65,000):
1. Cheques issued but not presented: Increases cash book balance relative to pass book -> Deduct from overdraft / Add: +₹28,000.
2. Cheques deposited but not credited: Decreases pass book balance -> Increase overdraft / Subtract: -₹36,000.
3. Bank charges & interest debited by bank (-₹4,000): Not yet recorded in Cash Book -> Increase overdraft / Subtract: -₹4,000.
4. Direct deposit by customer: Increases pass book balance -> Deduct from overdraft / Add: +₹14,000.
Net overdraft as per Pass Book = -₹65,000 + ₹28,000 - ₹36,000 - ₹4,000 + ₹14,000 = -₹63,000 (Overdraft of ₹63,000).',
                'tags' => 'BRS;Bank Overdraft;Timing Differences',
                'source' => 'ICAI CA Foundation / DU B.Com Core',
                'status' => 'published',
                'option_a' => 'Overdraft of ₹77,000',
