                'type' => 'mcq_single',
                'difficulty' => 'hard',
                'usage' => 'both',
                'marks' => 1,
                'negative_marks' => 0.25,
                'question' => 'A firm purchased a heavy industrial boiler on 1 October 2021 for ₹10,00,000. Depreciation has been provided at 20% p.a. under the Written Down Value (WDV) method on 31 March each year. On 1 January 2025, one-fourth of the boiler was destroyed by an accident and salvage realized ₹28,000, while the insurance company admitted a claim of ₹75,000 in full settlement. What was the net profit or loss on the destroyed portion of the boiler?',
                'explanation' => 'Cost of 1/4th portion = ₹2,50,000 on 1 Oct 2021.
Depreciation for FY 21-22 (6 months @ 20%): ₹2,50,000 * 20% * 6/12 = ₹25,000. WDV at 31/03/2022 = ₹2,25,000.
Depreciation for FY 22-23 (12 months @ 20%): ₹2,25,000 * 20% = ₹45,000. WDV at 31/03/2023 = ₹1,80,000.
Depreciation for FY 23-24 (12 months @ 20%): ₹1,80,000 * 20% = ₹36,000. WDV at 31/03/2024 = ₹1,44,000.
Depreciation for FY 24-25 up to 1 Jan 2025 (9 months @ 20%): ₹1,44,000 * 20% * 9/12 = ₹21,600.
WDV at date of destruction (1 Jan 2025) = ₹1,44,000 - ₹21,600 = ₹1,22,400.
Total recovery = Insurance claim (₹75,000) + Salvage (₹28,000) = ₹1,03,000.
Loss on accident = WDV - Total Recovery = ₹1,22,400 - ₹1,03,000 = ₹19,400.',
                'tags' => 'Depreciation;WDV Method;Asset Disposal;Insurance Settlement',
                'source' => 'ICAI CA Foundation / Corporate Accounting Exam',
                'status' => 'published',
                'option_a' => 'Loss of ₹19,400',
                'option_b' => 'Loss of ₹41,000',
                'option_c' => 'Profit of ₹6,600',
                'option_d' => 'Loss of ₹12,800',
                'correct' => 'A',
