                'negative_marks' => 0.25,
                'question' => 'A trader sold goods list-priced at ₹1,00,000 to Raman on credit, allowing a trade discount of 15% and a cash discount of 4% if payment was settled within 15 days. Raman paid 60% of the net invoice amount on the 10th day via bank draft. What amount should be credited to Raman\'s personal ledger account on receipt of this payment?',
                'explanation' => 'List Price = ₹1,00,000. Less Trade Discount @ 15% = ₹15,000. Invoice / Debt Amount = ₹85,000.
Raman settles 60% of invoice value: 60% of ₹85,000 = ₹51,000 of debt.
Since he pays within the discount window, he is eligible for a 4% cash discount on this portion: 4% of ₹51,000 = ₹2,040.
Cash / Bank draft paid = ₹51,000 - ₹2,040 = ₹48,960.
However, Raman\'s account must be credited with the full debt portion discharged, which is ₹51,000 (₹48,960 Bank + ₹2,040 Discount Allowed).',
                'tags' => 'Trade Discount;Cash Discount;Subsidiary Books;Journal Entries',
                'source' => 'ICAI CA Foundation Principles & Practice of Accounting',
                'status' => 'published',
                'option_a' => '₹48,960',
                'option_b' => '₹51,000',
                'option_c' => '₹50,000',
                'option_d' => '₹46,920',
                'correct' => 'B',
            ],
            [
                'external_id' => 'BCOM-FA-007',
