1. Further bad debts to be written off: ₹20,000.
2. Maintain a provision for doubtful debts @ 5% on debtors.
3. Create a reserve for discount on debtors @ 2%.
What is the net amount to be debited to the Profit and Loss Account for bad debts and provisions combined?',
                'explanation' => 'Step 1: Gross Debtors = ₹4,20,000. Less further bad debts = ₹20,000. Adjusted Debtors = ₹4,00,000.
Step 2: New Provision for Doubtful Debts = 5% of ₹4,00,000 = ₹20,000.
Step 3: Good debtors after doubtful debt provision = ₹4,00,000 - ₹20,000 = ₹3,80,000.
Reserve for discount on debtors = 2% of ₹3,80,000 = ₹7,600.
Step 4: P&L debit for Bad Debts & Doubtful Debts Provision:
Old Bad Debts (₹14,000) + Further Bad Debts (₹20,000) + New Provision (₹20,000) - Old Provision (₹26,000) = ₹28,000.
Step 5: Combined debit = Bad debt net cost (₹28,000) + Reserve for Discount (₹7,600) = ₹35,600.',
