                'question' => 'Under Ind AS 2 (Inventories), which of the following costs must be EXCLUDED from the cost of inventory and recognised as an expense in the period in which it is incurred?',
                'explanation' => 'Ind AS 2 paragraph 16 explicitly excludes from the cost of inventories and recognises as expenses in the period incurred:
(a) Abnormal amounts of wasted materials, labour or other production costs;
