                'question' => 'Prior to the preparation of final accounts, an accountant detected that a credit sale of ₹8,900 to Mohan was correctly entered in the Sales Day Book but posted to the debit of Sohan\'s account as ₹9,800. If a Suspense Account had already been created for the difference in the Trial Balance, what is the exact rectification entry?',
                'explanation' => 'Mohan\'s account was omitted from debit: Debit Mohan with ₹8,900.
