                'usage' => 'both',
                'marks' => 1,
                'negative_marks' => 0.25,
                'question' => 'Zenith Ltd. invited applications for 1,00,000 equity shares of ₹10 each at a premium of ₹2 per share, payable: ₹3 on application, ₹5 on allotment (including premium), and ₹4 on first and final call. Applications were received for 1,50,000 shares. Allotment was made on a pro-rata basis to all applicants. Surplus application money was adjusted towards allotment. Rajesh, who was allotted 600 shares, failed to pay allotment and call money. His shares were subsequently forfeited. What is the amount credited to the Share Forfeiture Account for Rajesh?',
                'explanation' => 'Rajesh was allotted 600 shares. Ratio of application to allotment = 1,50,000 / 1,00,000 = 3:2.
Rajesh applied for: 600 * (3/2) = 900 shares.
Application money paid by Rajesh = 900 * ₹3 = ₹2,700.
Application money required on allotted shares = 600 * ₹3 = ₹1,800.
Surplus application money adjusted on allotment = ₹2,700 - ₹1,800 = ₹900.
Allotment due on 600 shares = 600 * ₹5 = ₹3,000 (consisting of ₹1,800 face value + ₹1,200 securities premium).
Under Section 52 of Companies Act 2013, the surplus ₹900 is first adjusted towards the capital portion of allotment (₹1,800). Premium remains unpaid.
Amount forfeited = Total cash actually received towards share capital = Application money (₹1,800) + Advance adjusted towards capital (₹900) = ₹2,700.',
                'tags' => 'Pro-Rata Allotment;Share Forfeiture;Securities Premium;Companies Act 2013',
                'source' => 'ICAI CA Intermediate Corporate Accounting',
                'status' => 'published',
                'option_a' => '₹1,800',
                'option_b' => '₹2,700',
                'option_c' => '₹2,100',
                'option_d' => '₹3,000',
                'correct' => 'B',
