                'question' => 'Under Ind AS 103 (Business Combinations), how is the purchase consideration in an amalgamation accounting transaction measured, and where does any resulting excess of net identifiable assets acquired over consideration transferred get recognised?',
                'explanation' => 'Under Ind AS 103, consideration transferred is measured at acquisition-date fair value. If the net of acquisition-date amounts of identifiable assets acquired and liabilities assumed exceeds the consideration transferred, the acquirer has a bargain purchase. After reassessing whether all assets and liabilities were correctly identified, the gain on bargain purchase is recognised in Other Comprehensive Income (OCI) on the acquisition date and accumulated in equity as Capital Reserve.',
