                'marks' => 1,
                'negative_marks' => 0.25,
                'question' => 'A firm has capital employed of ₹40,00,000. Its normal rate of return in the industry is 12%. The net profits of the firm for the last four years were ₹5,20,000, ₹5,80,000, ₹6,40,000, and ₹6,60,000. Remuneration to partners of ₹60,000 p.a. is to be provided out of profits. If goodwill is valued at 3 years\' purchase of Super Profits, what is the value of goodwill?',
                'explanation' => '1. Average Profit = (5,20,000 + 5,80,000 + 6,40,000 + 6,60,000) / 4 = ₹6,00,000.
2. Adjusted Average Future Maintainable Profit = ₹6,00,000 - ₹60,000 = ₹5,40,000.
3. Normal Profit = Capital Employed * Normal Rate of Return = ₹40,00,000 * 12% = ₹4,80,000.
4. Super Profit = Future Maintainable Profit - Normal Profit = ₹5,40,000 - ₹4,80,000 = ₹60,00,000.
5. Goodwill = 3 * Super Profit = 3 * ₹60,000 = ₹1,80,000.',
                'tags' => 'Goodwill Valuation;Super Profits Method;Capital Employed',
                'source' => 'ICAI CA Intermediate / B.Com Corporate Accounting',
                'status' => 'published',
                'option_a' => '₹1,80,000',
                'option_b' => '₹2,40,000',
                'option_c' => '₹3,60,000',
                'option_d' => '₹1,20,000',
                'correct' => 'A',
