                'negative_marks' => 0.25,
                'question' => 'H Ltd. acquired 75% of the equity shares of S Ltd. on 1 July 2024. S Ltd.\'s financial year ends on 31 March 2025. On 1 April 2024, S Ltd. had a General Reserve of ₹1,60,000 and Profit & Loss balance of ₹80,000. Profit earned by S Ltd. during FY 2024-25 was ₹2,40,000 earned evenly throughout the year. What is the total Pre-Acquisition Profit attributable to H Ltd. for consolidation purposes?',
                'explanation' => 'Pre-acquisition period is 1 April 2024 to 1 July 2024 = 3 months.
