Current year\'s pre-acquisition profit (3 months): ₹2,40,000 * (3/12) = ₹60,000.
Total Pre-Acquisition Profits of S Ltd. = ₹2,40,000 + ₹60,000 = ₹3,00,000.
H Ltd.\'s share (75%) = 75% of ₹3,00,000 = ₹2,25,000 (treated as Capital Profit and adjusted against Cost of Investment for Goodwill/Capital Reserve calculation).',
