                'question' => 'A multi-product firm manufactures two products, Alpha and Beta. Alpha has a selling price of ₹50, variable cost of ₹30, and represents 60% of total sales revenue. Beta has a selling price of ₹100, variable cost of ₹40, and represents 40% of sales revenue. Total annual fixed costs are ₹14,40,000. What is the overall composite break-even sales revenue of the firm?',
