                'question' => 'Standard cost card specifies 4 kg of raw material at ₹25 per kg per unit of finished product. During March, 3,000 units were produced, consuming 12,600 kg of raw material purchased at ₹24 per kg. What are the Material Price Variance (MPV) and Material Usage Variance (MUV)?',
                'explanation' => 'Standard Quantity for Actual Output (SQ) = 3,000 * 4 = 12,000 kg.
Actual Quantity (AQ) = 12,600 kg.
Standard Price (SP) = ₹25/kg.
Actual Price (AP) = ₹24/kg.
1. Material Price Variance (MPV) = AQ * (SP - AP) = 12,600 * (25 - 24) = ₹12,600 Favourable (F).
2. Material Usage Variance (MUV) = SP * (SQ - AQ) = 25 * (12,000 - 12,600) = 25 * (-600) = ₹15,000 Adverse (A).
Total Material Cost Variance (MCV) = ₹12,600 F + ₹15,000 A = ₹2,400 Adverse.',
