                'question' => 'An engineering factory uses 8,000 components annually. Ordering cost is ₹180 per order, purchase price is ₹200 per component, and annual inventory holding cost is 10% of purchase price. What is the Economic Order Quantity (EOQ)?',
                'explanation' => 'Annual Demand (A) = 8,000 units.
Ordering Cost per order (O) = ₹180.
Carrying Cost per unit per annum (C) = 10% of ₹200 = ₹20.
