Let\'s calculate for A = 10,000 components, O = ₹100, C = ₹20: EOQ = sqrt(2 * 10000 * 100 / 20) = sqrt(1,00,000) = 316.2. If O = ₹160 and C = ₹16 (8% of 200): EOQ = sqrt(2 * 8000 * 160 / 16) = sqrt(1,60,000) = 400 units.',
                'tags' => 'EOQ;Inventory Management;Carrying Cost',
