                'question' => 'In Process II of a chemical plant, 10,000 units were introduced at a cost of ₹1,60,000. Material, Labour, and Overhead incurred in Process II totaled ₹1,16,000. Normal loss is 5% of input, realizable as scrap at ₹4 per unit. Actual output transferred to finished goods was 9,300 units. What is the value of the abnormal loss charged to the Costing Profit and Loss Account?',
                'explanation' => 'Input = 10,000 units. Normal Loss = 5% of 10,000 = 500 units.
Normal Output expected = 10,000 - 500 = 9,500 units.
Actual Output = 9,300 units. Abnormal Loss = 9,500 - 9,300 = 200 units.
Total Costs = ₹1,60,000 + ₹1,16,000 = ₹2,76,000.
Scrap value of normal loss = 500 units * ₹4 = ₹2,000.
Net Normal Cost = ₹2,76,000 - ₹2,000 = ₹2,74,000.
Cost per effective unit = ₹2,74,000 / 9,500 units = ₹28.8421 per unit.
Value of Abnormal Loss = 200 units * ₹28.8421 = ₹5,768.42 (approx ₹5,768).',
