                'question' => 'A worker is allowed 10 hours to complete a job at a basic wage rate of ₹80 per hour. The worker completes the task in 6 hours. What are the total earnings of the worker under the Rowan Incentive Plan?',
                'explanation' => 'Standard Time (S) = 10 hours. Actual Time (T) = 6 hours. Time Saved (S - T) = 4 hours. Wage Rate (R) = ₹80/hr.
Basic Wages = T * R = 6 * ₹80 = ₹480.
Rowan Bonus Formula = (Time Saved / Standard Time) * (Actual Time * Wage Rate) = (4 / 10) * (6 * ₹80) = 0.40 * ₹480 = ₹192.
