                'question' => 'Company X sells its product at ₹20 per unit. At a sales level of 50,000 units, the Margin of Safety is 40% and total variable costs are ₹6,00,000. What is the company\'s total annual Fixed Cost?',
                'explanation' => 'Total Sales Revenue = 50,000 * ₹20 = ₹10,00,000.
Total Variable Costs = ₹6,00,000. Contribution = ₹10,00,000 - ₹6,00,000 = ₹4,00,000.
P/V Ratio = Contribution / Sales = 4,00,000 / 10,00,000 = 40%.
Margin of Safety % = (Total Sales - Break-even Sales) / Total Sales = 40%.
