                'marks' => 1,
                'negative_marks' => 0.25,
                'question' => 'A corporate entity has the following capital structure:
- Equity Share Capital (market value ₹60,00,000, beta = 1.30)
- 10% Redeemable Debt (market value ₹40,00,000, issued at par)
The risk-free rate of return is 6.5%, the expected return on the market portfolio is 14.5%, and the corporate tax rate is 25%. What is the Weighted Average Cost of Capital (WACC) of the firm?',
                'explanation' => '1. Cost of Equity (Ke) via CAPM = Rf + beta * (Rm - Rf) = 6.5% + 1.30 * (14.5% - 6.5%) = 6.5% + 1.30 * 8.0% = 6.5% + 10.4% = 16.9%.
2. Post-tax Cost of Debt (Kd) = Coupon Rate * (1 - Tax Rate) = 10% * (1 - 0.25) = 7.5%.
3. Total Market Value = ₹60,00,000 + ₹40,00,000 = ₹1,00,00,000.
Weight of Equity (We) = 60/100 = 0.60; Weight of Debt (Wd) = 40/100 = 0.40.
4. WACC = (We * Ke) + (Wd * Kd) = (0.60 * 16.9%) + (0.40 * 7.5%) = 10.14% + 3.00% = 13.14%.',
                'tags' => 'WACC;CAPM;Cost of Equity;Cost of Debt;Tax Shield',
                'source' => 'Oxford Saïd Finance Core / ICAI FM Standard',
                'status' => 'published',
                'option_a' => '13.14%',
                'option_b' => '14.25%',
                'option_c' => '12.80%',
                'option_d' => '15.00%',
                'correct' => 'A',
            ],
