                'marks' => 1,
                'negative_marks' => 0.25,
                'question' => 'Apex Corp has sales of ₹50,00,000 with a P/V ratio of 40%. Fixed operating costs are ₹8,00,000 and 12% debentures outstanding are ₹50,00,000. If sales increase by 10%, what will be the percentage change in Earnings Before Taxes (EBT)?',
                'explanation' => '1. Contribution = 40% of ₹50,00,000 = ₹20,00,000.
2. EBIT = Contribution - Fixed Costs = ₹20,00,000 - ₹8,00,000 = ₹12,00,000.
3. Interest = 12% of ₹50,00,000 = ₹6,00,000.
4. EBT = EBIT - Interest = ₹12,00,000 - ₹6,00,000 = ₹6,00,000.
5. Degree of Operating Leverage (DOL) = Contribution / EBIT = 20,00,000 / 12,00,000 = 1.6667.
6. Degree of Financial Leverage (DFL) = EBIT / EBT = 12,00,000 / 6,00,000 = 2.0.
7. Degree of Total Leverage (DTL) = DOL * DFL = 1.6667 * 2.0 = 3.3333.
Percentage change in EBT = DTL * % change in sales = 3.3333 * 10% = 33.33%.',
                'tags' => 'Operating Leverage;Financial Leverage;Combined Leverage;EBIT-EPS',
                'source' => 'ICAI CA Intermediate Financial Management',
                'status' => 'published',
