                'question' => 'A company\'s share is currently trading at ₹120. It has just paid an annual dividend of ₹6.00 per share. Dividends are expected to grow at a perpetual compound rate of 5% per annum. What is the cost of equity (Ke) using Gordon\'s Dividend Growth Model?',
                'explanation' => 'Gordon\'s Model: Ke = (D1 / P0) + g
D0 = ₹6.00 (just paid). Next expected dividend D1 = D0 * (1 + g) = ₹6.00 * (1 + 0.05) = ₹6.30.
Current Market Price P0 = ₹120. Growth rate g = 5% = 0.05.
Ke = (6.30 / 120) + 0.05 = 0.0525 + 0.05 = 0.1025 = 10.25%.',
                'tags' => 'Cost of Equity;Gordon Model;Dividend Discount Model',
