                'explanation' => 'Under Section 6(1A) of the Income-tax Act, 1961, an individual who is an Indian citizen shall be deemed to be a resident in India in any previous year if his total income (other than foreign source income) exceeds ₹15,00,000 and he is not liable to tax in any other country or territory by reason of his domicile, residence, or any other criteria of similar nature. Furthermore, under Section 6(6)(d), a deemed resident under Section 6(1A) is always classified as a \'Resident but Not Ordinarily Resident\' (RNOR).',
