                'question' => 'Mr. Sharma resides in Chennai and receives basic salary of ₹60,000 per month, Dearness Allowance (forming part of retirement benefits) of ₹20,000 per month, and House Rent Allowance (HRA) of ₹25,000 per month. He pays actual rent of ₹28,000 per month for his rented accommodation. Under Section 10(13A) and Rule 2A of the Income-tax Rules, what is the monthly exempt amount of HRA?',
                'explanation' => 'Salary for HRA = Basic + DA (forming part) = ₹60,000 + ₹20,000 = ₹80,000 per month.
