2. Rent paid minus 10% of Salary = ₹28,000 - 10%(₹80,000) = ₹28,000 - ₹8,000 = ₹20,000/month
3. 50% of salary (for metro cities like Chennai) = 50% of ₹80,000 = ₹40,000/month
