                'question' => 'An assessee acquired listed equity shares of ABC Ltd. on 10 June 2022 for ₹5,00,000 and sold them on 12 August 2024 through a recognized stock exchange for ₹12,00,000, paying Securities Transaction Tax (STT) on both purchase and sale. Under Section 112A of the Income-tax Act, 1961 (as amended by Finance Act 2024), what is the Long-Term Capital Gains (LTCG) tax liability?',
                'explanation' => 'Holding period is June 2022 to August 2024 (> 12 months for listed equity), so it is Long-Term Capital Gain.
Capital Gain = Sale Price - Cost = ₹12,00,000 - ₹5,00,000 = ₹7,00,000.
Under Section 112A (amended by Finance Act 2024):
Exemption threshold on LTCG under Section 112A is ₹1,25,000.
Taxable LTCG = ₹7,00,000 - ₹1,25,000 = ₹5,75,000.
Tax rate under Section 112A is 12.5% (increased from 10% by Finance Act 2024).
Basic tax = 12.5% of ₹5,75,000 = ₹71,875. Adding 4% Health & Education Cess = ₹71,875 * 1.04 = ₹74,750.',
