                'question' => 'Under Section 13(2) of the CGST Act, 2017, an architectural firm in Mumbai provides design services to a client on 10 April 2024. The invoice for the service is issued on 25 May 2024. Payment is received in the bank account on 18 May 2024, and recorded in the books of account on 20 May 2024. What is the Time of Supply of service?',
                'explanation' => 'Under Section 13(2) of the CGST Act:
