                'question' => 'An Indian importer imports industrial equipment from Germany with an FOB value of €10,000. Sea freight actually incurred was €2,500, transit insurance was €150, and port handling charges in India were ₹10,000. The CBIC notified exchange rate on the date of presentation of the Bill of Entry is ₹90 per Euro. What is the Assessable Value (AV) of the consignment under Section 14 of the Customs Act, 1962?',
                'explanation' => 'Under Customs Valuation Rules:
FOB Value = €10,000.
Freight: For sea transport, freight is actual cost or 20% of FOB, whichever is lower. 20% of FOB = 20% of €10,000 = €2,000. Actual is €2,500, so freight is capped at €2,000.
Insurance: Actual insurance is €150 (if unidentifiable, 1.125% of FOB). Actual €150 is added.
CIF Assessable Value in Euro = €10,000 (FOB) + €2,000 (Freight capped at 20%) + €150 (Insurance) = €12,150.
Convert to INR at CBIC rate: €12,150 * ₹90 = ₹10,93,500.
(Port handling charges / Landing charges in India were abolished from the valuation rule by notification in 2017).',
                'tags' => 'Customs Valuation;Assessable Value;Customs Act 1962;Sea Freight',
                'source' => 'Customs Act 1962 / ICAI CA Intermediate Customs',
                'status' => 'published',
                'option_a' => '₹10,93,500',
                'option_b' => '₹11,38,500 (using uncapped actual freight)',
                'option_c' => '₹11,03,500',
                'option_d' => '₹9,00,000',
                'correct' => 'A',
