                'question' => 'Under Modigliani-Miller Proposition II with Corporate Taxes, if an unlevered firm has a cost of equity of r0 = 14%, cost of debt rd = 8%, corporate tax rate Tc = 25%, and maintains a Debt-to-Equity (D/E) ratio of 0.80, what is the levered firm\'s cost of equity (re)?',
                'explanation' => 'MM Proposition II with Corporate Taxes Formula:
re = r0 + (r0 - rd) * (1 - Tc) * (D / E)
re = 14% + (14% - 8%) * (1 - 0.25) * 0.80
re = 14% + 6% * 0.75 * 0.80 = 14% + 4.5% * 0.80 = 14% + 3.6% = 17.6%.',
