                'question' => 'Using Walter\'s Model of dividend valuation: Earnings per share E = ₹10, Cost of capital Ke = 10%, and Internal rate of return on retained earnings r = 15%. If the firm pays a dividend D = ₹4 per share, what is the market price of the share (P)?',
                'explanation' => 'Walter\'s Formula:
