                'marks' => 1,
                'negative_marks' => 0.25,
                'question' => 'A company produces two products, Standard (10,000 units) and Special (2,000 units). Total machine setup costs are ₹6,00,000. Under traditional volume-based costing, setups are allocated based on total direct machine hours (Standard uses 40,000 hours, Special uses 10,000 hours). Under Activity-Based Costing (ABC), setup costs are driven by the number of production runs (Standard requires 20 runs, Special requires 40 runs). What is the setup cost allocated per unit of Special under Traditional Costing versus ABC?',
                'explanation' => '1. Traditional Costing:
Total machine hours = 40,000 + 10,000 = 50,000 hours.
Overhead rate = ₹6,00,000 / 50,000 = ₹12 per machine hour.
Special machine hours = 10,000 hours -> Total setup allocated = 10,000 * ₹12 = ₹1,20,000.
Setup cost per unit of Special = ₹1,20,000 / 2,000 units = ₹60 per unit.
2. Activity-Based Costing (ABC):
Total setup runs = 20 + 40 = 60 runs.
Cost per run = ₹6,00,000 / 60 = ₹10,000 per run.
Special runs = 40 runs -> Total setup allocated = 40 * ₹10,000 = ₹4,00,000.
Setup cost per unit of Special under ABC = ₹4,00,000 / 2,000 units = ₹200 per unit.
Traditional costing severely under-costed Special by ₹140 per unit.',
                'tags' => 'Activity-Based Costing;Cost Drivers;Cost Distortion;Traditional Allocation',
                'source' => 'Cooper & Kaplan (1988) / ICMAI Advanced Costing',
                'status' => 'published',
                'option_a' => 'Traditional: ₹60 per unit; ABC: ₹200 per unit',
