                'question' => 'Division A manufactures a component with variable cost ₹40 and full absorption cost ₹60. The component can be sold externally in a perfectly competitive market for ₹90. Division A is currently operating at 100% capacity. Division B of the same company requests 5,000 units of this component. What is the optimal minimum transfer price per unit that preserves goal congruence for the company as a whole?',
                'explanation' => 'General Transfer Price Rule:
Minimum Transfer Price = Additional Outlay Cost per unit + Opportunity Cost per unit.
Since Division A is operating at full capacity, transferring to Division B requires sacrificing external sales at ₹90.
Outlay Cost = Variable Cost = ₹40.
Opportunity Cost = Lost Contribution per unit = External Selling Price (₹90) - Variable Cost (₹40) = ₹50.
Minimum Transfer Price = ₹40 + ₹50 = ₹90 (Market Price).',
