                'question' => 'A draws a 3-month accommodation bill for ₹60,000 on B on 1 January 2025. B accepts the bill for mutual accommodation. A gets the bill discounted with his bank on 4 January at 12% p.a. and remits one-third of the proceeds to B. What amount of cash proceeds does B receive from A?',
