Cost of Sales = 80% of ₹56,000 = +₹44,800.
Less: Purchases received and included in stock up to 7 April = ₹45,000 - ₹8,000 = -₹37,000.
Value of inventory on 31 March 2025 = ₹3,80,000 + ₹44,800 - ₹37,000 = ₹3,87,800.',
