                'question' => 'A and B are partners sharing profits in the ratio 2:1 with capital balances of ₹2,00,000 and ₹1,00,000 respectively. They admit C into the partnership for a 1/4th share in future profits. C brings in ₹1,50,000 as his capital. No goodwill account is to be opened. What is the value of \'Hidden Goodwill\' of the reconstituted firm?',
                'explanation' => 'Hidden Goodwill calculation:
Total capital of the new firm based on C\'s investment = C\'s Capital * (1 / C\'s Share) = ₹1,50,000 * (4 / 1) = ₹6,00,000.
Actual combined net worth / capital of all partners = A\'s Capital (₹2,00,000) + B\'s Capital (₹1,00,000) + C\'s Capital (₹1,50,000) = ₹4,50,000.
Hidden Goodwill = Capitalized Value - Actual Capital = ₹6,00,000 - ₹4,50,000 = ₹1,50,000.
(C\'s share of goodwill = 1/4 of ₹1,50,000 = ₹37,500, credited to sacrificing partners).',
