                'negative_marks' => 0.25,
                'question' => 'A petroleum refining process produces two joint products, J1 and J2, incurring total joint processing costs of ₹15,00,000 up to the split-off point. J1 produces 10,000 litres and can be sold at split-off for ₹80/litre. J2 produces 5,000 litres and requires further processing costing ₹2,00,000 after which it sells for ₹160/litre. Using the Net Realisable Value (NRV) method, what amount of joint cost is apportioned to Product J2?',
                'explanation' => 'NRV of J1 = 10,000 * ₹80 = ₹8,00,000.
NRV of J2 = Final Sales Value (5,000 * ₹160 = ₹8,00,000) minus Further Processing (₹2,00,000) = ₹6,00,000.
Total NRV = ₹8,00,000 + ₹6,00,000 = ₹14,00,000.
Ratio of J1 to J2 = 8 : 6 = 4 : 3.
Joint Cost apportioned to J2 = (6 / 14) * ₹15,00,000 = (3 / 7) * ₹15,00,000 = ₹6,42,857.',
                'tags' => 'Joint Products;NRV Method;Split-off Point;Cost Apportionment',
